package com.trampolim.api.observatory;
import java.util.*;import com.trampolim.api.security.PlatformAccess;import com.trampolim.api.radar.RadarBridge;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class ObservatoryController {
 private final EmploymentObservatory service;private final PlatformAccess platform;private final RadarBridge bridge;
 public ObservatoryController(EmploymentObservatory service,PlatformAccess platform,RadarBridge bridge){this.service=service;this.platform=platform;this.bridge=bridge;}
 public record LearningQuery(String fromMonth,String toMonth,String state){}
 private void admin(String email){if(!platform.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Indicadores operacionais restritos à administração global.");}
 @GetMapping("/api/public/career/observatory/indicators")public Map<String,Object> overview(@RequestParam String fromMonth,@RequestParam String toMonth,@RequestParam(defaultValue="")String state,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="")String municipalityCode,jakarta.servlet.http.HttpServletRequest request){return service.overview(fromMonth,toMonth,state,region,municipalityCode,request.getRemoteAddr(),false);}
 @GetMapping("/api/public/career/observatory/distribution")public Map<String,Object> distribution(@RequestParam String fromMonth,@RequestParam String toMonth,@RequestParam(defaultValue="")String state,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="")String municipalityCode,@RequestParam String dimension,@RequestParam(defaultValue="0")int offset,@RequestParam(defaultValue="20")int limit,jakarta.servlet.http.HttpServletRequest request){return service.distribution(fromMonth,toMonth,state,region,municipalityCode,dimension,offset,limit,request.getRemoteAddr());}
 @GetMapping("/api/admin/observatory/indicators")public Map<String,Object> privateOverview(@AuthenticationPrincipal String email,@RequestParam String fromMonth,@RequestParam String toMonth,@RequestParam(defaultValue="")String state,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="")String municipalityCode){admin(email);return service.overview(fromMonth,toMonth,state,region,municipalityCode,email,true);}
 @GetMapping("/api/admin/observatory/status")public Map<String,Object> status(@AuthenticationPrincipal String email){admin(email);return service.health();}
 @PostMapping("/api/admin/observatory/refresh")@ResponseStatus(HttpStatus.ACCEPTED)public Map<String,Object> refresh(@AuthenticationPrincipal String email){admin(email);var result=new LinkedHashMap<String,Object>();result.put("employment",service.enqueue());try{result.put("learning",bridge.convert(bridge.post("/integrations/career/observatory/v2/learning/refresh",Map.of()),Map.class));}catch(ResponseStatusException failure){result.put("learning",Map.of("status","UNAVAILABLE"));}return result;}
 @GetMapping("/api/public/career/observatory/definitions")public Map<String,Object> definitions(){return MetricDefinitions.all();}
}
